from copy import deepcopy
import unittest

from atlas.search import search
from atlas.service import DocumentService


class SearchTests(unittest.TestCase):
    def setUp(self):
        self.searchers = (search, DocumentService().search_documents)

    def test_all_tokens_across_title_and_body_with_id_order(self):
        records = [
            {"id": "z", "title": "Atlas", "body": "Release 42"},
            {"id": "partial", "title": "Atlas", "body": "Release"},
            {"id": "a", "title": "RELEASE-42", "body": "ATLAS atlas"},
            {"id": "none", "title": "Other", "body": "Document"},
        ]
        original = deepcopy(records)
        for searcher in self.searchers:
            with self.subTest(searcher=searcher):
                result = searcher(records, "ATLAS, release_42 atlas")
                self.assertEqual([record["id"] for record in result], ["a", "z"])
                self.assertEqual(records, original)

    def test_partial_token_substrings_do_not_match(self):
        records = [
            {"id": "a", "title": "Atlas", "body": "catalog 420"},
            {"id": "b", "title": "Atlas", "body": "cat 42"},
        ]
        for searcher in self.searchers:
            for query in ("cat", "42", "atlas cat 42"):
                with self.subTest(searcher=searcher, query=query):
                    self.assertEqual(searcher(records, query), [records[1]])

    def test_empty_normalized_queries_and_empty_records(self):
        records = [{"id": "a", "title": "Atlas", "body": "Document"}]
        for searcher in self.searchers:
            for query in ("", " \t", "!_--"):
                with self.subTest(searcher=searcher, query=query):
                    self.assertEqual(searcher(records, query), [])
            self.assertEqual(searcher([], "atlas"), [])


if __name__ == "__main__":
    unittest.main()
